int myRecursiveFunc(int a, int b){
    if (a % b == 2)
        return a;
    else {
        cout << (a+b) << " " << (a-b) << endl;   // sonraki çağrının parametreleri
        return b + myRecursiveFunc(a+b, a-b);
    }
}
int main(){
    cout << myRecursiveFunc(5, 2) << endl;
    return 0;
}
